extern "C" void Stub_glRenderbufferStorage(GLenum target, GLenum internalformat, GLsizei width, GLsizei height) { 
    GLint bound_rbo = 0; glGetIntegerv(GL_RENDERBUFFER_BINDING, &bound_rbo); if (bound_rbo == 0) return; 
    // ВРЕМЕННЫЙ ЭКСПЕРИМЕНТ A6: поднять 16-битную глубину до 24, чтобы проверить z-fighting.
    if (g_a6Depth24 && internalformat == 0x81A5) internalformat = 0x81A6;
    if (A6Dbg()) {   // ВРЕМЕННАЯ ДИАГНОСТИКА A6: какой буфер на самом деле просит игра
        static std::set<uint64_t> seenRb;
        uint64_t k = ((uint64_t)internalformat << 32) | ((uint64_t)width << 16) | (uint64_t)height;
        if (seenRb.size() < 16 && seenRb.insert(k).second) {
            char b[128];
            snprintf(b, sizeof(b), "[A6-RBST] rb=%d fmt=0x%x %dx%d", (int)bound_rbo, (unsigned)internalformat, (int)width, (int)height);
            _LogToJava(b);
        }
    }
    if (g_gpuOffloadMask & 64) glRenderbufferStorage(target, internalformat, width, height); 
}
extern "C" GLenum Stub_glCheckFramebufferStatus(GLenum target) { 
    GLint bound_fbo = 0; glGetIntegerv(GL_FRAMEBUFFER_BINDING, &bound_fbo); if (bound_fbo == 0) return GL_FRAMEBUFFER_COMPLETE; 
    if (g_gpuOffloadMask & 64) {
        GLenum st = glCheckFramebufferStatus(target);
        if (A6Dbg()) {   // ВРЕМЕННАЯ ДИАГНОСТИКА A6: почему пропадает проход в RTT
            static std::set<uint64_t> seenFbo;
            uint64_t k = ((uint64_t)bound_fbo << 32) | (uint64_t)st;
            if (seenFbo.size() < 16 && seenFbo.insert(k).second) {
                char b[96];
                snprintf(b, sizeof(b), "[A6-FBOST] fbo=%d status=0x%x", (int)bound_fbo, (unsigned)st);
                LogToJava(b);
            }
        }
        return st;
    }
    return GL_FRAMEBUFFER_COMPLETE;
}
extern "C" void Stub_glGetRenderbufferParameteriv(GLenum target, GLenum pname, GLint *params) { 
    uint32_t lr = (uint32_t)__builtin_return_address(0);
    if (pname == 0x8D42) { 
        *params = g_surfaceWidth; 
        LogToJava(">>>>>>>> [SIZE-CRITICAL] glGetRenderbufferParameteriv(WIDTH) <<<<<<<<");
        LogToJava("  Caller: " + GetModuleInfoForAddress(lr) + " | Отдаем: " + std::to_string(*params));
        return; 
    } 
    if (pname == 0x8D43) { 
        *params = g_surfaceHeight; 
        LogToJava(">>>>>>>> [SIZE-CRITICAL] glGetRenderbufferParameteriv(HEIGHT) <<<<<<<<");
        LogToJava("  Caller: " + GetModuleInfoForAddress(lr) + " | Отдаем: " + std::to_string(*params));
        return; 
    } 
    glGetRenderbufferParameteriv(target, pname, params); 
}

