extern "C" long wrap_sysconf(int name) {
    LogToJava("C-API-TRACE: [sysconf] name=" + std::to_string(name));
    if (name == 58) return 2; // _SC_NPROCESSORS_ONLN
    if (name == 57) return 2; // _SC_NPROCESSORS_CONF
    if (name == 29) return 4096; // _SC_PAGESIZE
    return sysconf(name);
}

// PTHREAD_MUTEX_INITIALIZER в iOS — это сигнатура в первом слове, а в bionic — нули.
// Подменять сигнатуру можно только через CAS: иначе два потока, одновременно взявшие
// статический мьютекс, успевают оба «проинициализировать» его, и повторный
// pthread_mutex_init сбрасывает уже захваченный замок в свободное состояние.
// У Darwin четыре статических инициализатора, и у каждого своя сигнатура. Обычный превращается
// в нули (это и есть готовый bionic-мьютекс), остальным нужен настоящий init с атрибутом —
// его делаем под глобальным замком, иначе второй поток успеет увидеть полуготовую структуру.
static pthread_mutex_t g_iosMutexInitLock = PTHREAD_MUTEX_INITIALIZER;
static inline void IosMutexEnsureInit(void* mutex) {
    uint32_t expected = 0x32AAABA7;
    if (__atomic_compare_exchange_n((uint32_t*)mutex, &expected, 0u, false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST))
        return;
    if (expected != 0x32AAABA1 && expected != 0x32AAABA2 && expected != 0x32AAABA3) return;
    pthread_mutex_lock(&g_iosMutexInitLock);
    uint32_t sig = __atomic_load_n((uint32_t*)mutex, __ATOMIC_SEQ_CST);
    if (sig == 0x32AAABA1 || sig == 0x32AAABA2 || sig == 0x32AAABA3) {
        pthread_mutexattr_t at;
        pthread_mutexattr_init(&at);
        pthread_mutexattr_settype(&at, sig == 0x32AAABA2 ? PTHREAD_MUTEX_RECURSIVE
                                     : sig == 0x32AAABA1 ? PTHREAD_MUTEX_ERRORCHECK
                                                         : PTHREAD_MUTEX_NORMAL);
        memset(mutex, 0, 40);
        pthread_mutex_init((pthread_mutex_t*)mutex, &at);
        pthread_mutexattr_destroy(&at);
    }
    pthread_mutex_unlock(&g_iosMutexInitLock);
}
static inline void IosCondEnsureInit(void* cond) {
    uint32_t expected = 0x3CB0B1BB;
    __atomic_compare_exchange_n((uint32_t*)cond, &expected, 0u, false, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
}

extern "C" int wrap_pthread_mutex_init(void* mutex, const void* attr) {
    memset(mutex, 0, 40); // iOS mutex = 40 bytes
    // pthread_mutexattr_* привязаны напрямую к bionic, поэтому attr уже в его формате.
    // Без него рекурсивный мьютекс становился обычным и игра вставала на себе самой.
    return pthread_mutex_init((pthread_mutex_t*)mutex, (const pthread_mutexattr_t*)attr);
}
extern "C" int wrap_pthread_mutex_lock(void* mutex) {
    IosMutexEnsureInit(mutex);
    return pthread_mutex_lock((pthread_mutex_t*)mutex);
}
extern "C" int wrap_pthread_mutex_trylock(void* mutex) {
    IosMutexEnsureInit(mutex);
    return pthread_mutex_trylock((pthread_mutex_t*)mutex);
}
extern "C" int wrap_pthread_mutex_unlock(void* mutex) {
    return pthread_mutex_unlock((pthread_mutex_t*)mutex);
}
extern "C" int wrap_pthread_mutex_destroy(void* mutex) {
    return pthread_mutex_destroy((pthread_mutex_t*)mutex);
}
extern "C" int wrap_pthread_cond_init(void* cond, const void* attr) {
    memset(cond, 0, 24); // iOS cond = 24 bytes
    return pthread_cond_init((pthread_cond_t*)cond, nullptr);
}
extern "C" int wrap_pthread_cond_wait(void* cond, void* mutex) {
    IosCondEnsureInit(cond);
    IosMutexEnsureInit(mutex);
    return pthread_cond_wait((pthread_cond_t*)cond, (pthread_mutex_t*)mutex);
}
extern "C" int wrap_pthread_cond_timedwait(void* cond, void* mutex, const struct timespec* abstime) {
    IosCondEnsureInit(cond);
    IosMutexEnsureInit(mutex);
    return pthread_cond_timedwait((pthread_cond_t*)cond, (pthread_mutex_t*)mutex, abstime);
}
extern "C" int wrap_pthread_cond_signal(void* cond) {
    IosCondEnsureInit(cond);
    return pthread_cond_signal((pthread_cond_t*)cond);
}
extern "C" int wrap_pthread_cond_broadcast(void* cond) {
    IosCondEnsureInit(cond);
    return pthread_cond_broadcast((pthread_cond_t*)cond);
}
extern "C" int wrap_pthread_cond_destroy(void* cond) {
    return pthread_cond_destroy((pthread_cond_t*)cond);
}

// В режиме ES 1.1 враппер обязан выглядеть устройством без ES 2.0, иначе игра
// грузит шейдеры «ES2-класса» и рассогласуется с фиксированным конвейером.
static const char* HleDeviceModel() {
    // Asphalt 6 исключена: на iPhone1,2 она уходит в урезанный набор ресурсов.
    return (g_esModeOption == 1 && !g_isAsphalt6) ? "iPhone1,2" : "iPhone2,1";
}

extern "C" int wrap_sysctlbyname(const char* name, void* oldp, size_t* oldlenp, void* newp, size_t newlen) {
    uint32_t lr = (uint32_t)__builtin_return_address(0);
    LogToJava(std::string(">>>>>>>> [SYSCTL-TRACE] sysctlbyname: ") + (name ? name : "null") + " | Caller: " + GetModuleInfoForAddress(lr) + " <<<<<<<<");
    if (name && (strcmp(name, "hw.machine") == 0 || strcmp(name, "hw.model") == 0)) {
        const char* machine = HleDeviceModel();
        if (oldlenp) {
            if (oldp && *oldlenp >= strlen(machine) + 1) {
                strcpy((char*)oldp, machine);
                LogToJava(std::string("  Отдали строку: ") + machine);
            }
            *oldlenp = strlen(machine) + 1;
            return 0;
        }
    }
    return -1;
}

extern "C" int wrap_sysctl(int* name, unsigned int namelen, void* oldp, size_t* oldlenp, void* newp, size_t newlen) {
    uint32_t lr = (uint32_t)__builtin_return_address(0);
    if (name && namelen > 0) {
        LogToJava(">>>>>>>> [SYSCTL-TRACE] sysctl: [" + std::to_string(name[0]) + (namelen > 1 ? ", " + std::to_string(name[1]) : "") + "] | Caller: " + GetModuleInfoForAddress(lr) + " <<<<<<<<");
    }
    if (name && namelen >= 2 && name[0] == 6) { // 6 = CTL_HW
        if (name[1] == 1 || name[1] == 2) { // 1 = HW_MACHINE, 2 = HW_MODEL
            const char* machine = HleDeviceModel();
            if (oldlenp) {
                if (oldp && *oldlenp >= strlen(machine) + 1) {
                    strcpy((char*)oldp, machine);
                    LogToJava(std::string("  Отдали строку: ") + machine);
                }
                *oldlenp = strlen(machine) + 1;
                return 0;
            }
        }
    }
    return -1;
}

// Байт 0 — «готово», байт 1 — «кто-то уже строит». Без второго байта и замка два потока
// одновременно возвращали 1 и конструировали один и тот же статик дважды: второй объект
// ложился поверх первого, и содержимое таблицы зависело от того, кто успел раньше.
static pthread_mutex_t g_guardLock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_guardCond = PTHREAD_COND_INITIALIZER;

extern "C" int wrap___cxa_guard_acquire(int32_t* guard) {
    char* g = (char*)guard;
    if (__atomic_load_n(g, __ATOMIC_ACQUIRE)) return 0;
    pthread_mutex_lock(&g_guardLock);
    int need = 0;
    for (;;) {
        if (g[0]) break;
        if (!g[1]) { g[1] = 1; need = 1; break; }
        pthread_cond_wait(&g_guardCond, &g_guardLock);
    }
    pthread_mutex_unlock(&g_guardLock);
    return need;
}
extern "C" void wrap___cxa_guard_release(int32_t* guard) {
    char* g = (char*)guard;
    pthread_mutex_lock(&g_guardLock);
    g[1] = 0;
    __atomic_store_n(g, (char)1, __ATOMIC_RELEASE);
    pthread_cond_broadcast(&g_guardCond);
    pthread_mutex_unlock(&g_guardLock);
}

