extern "C" int wrap_AudioFileGetPropertyInfo(void* inAudioFile, uint32_t inPropertyID, uint32_t* outDataSize, uint32_t* isWritable) {
    if (isWritable) *isWritable = 0;
    if (inPropertyID == 0x64666D74) { if (outDataSize) *outDataSize = 40; return 0; } // dfmt
    if (inPropertyID == 0x62636E74) { if (outDataSize) *outDataSize = 8; return 0; }  // bcnt
    if (inPropertyID == 0x70737A65) { if (outDataSize) *outDataSize = 4; return 0; }  // psze (MaximumPacketSize)
    if (inPropertyID == 0x70737562) { if (outDataSize) *outDataSize = 4; return 0; }  // psub (PacketSizeUpperBound)
    if (inPropertyID == 0x70636E74) { if (outDataSize) *outDataSize = 8; return 0; }  // pcnt (PacketCount)
    if (inPropertyID == 0x6D676963) { if (outDataSize) *outDataSize = 0; return -50; } // mgic (MagicCookie) - скипаем ошибкой
    
    char prop[5] = { (char)(inPropertyID >> 24), (char)((inPropertyID >> 16) & 0xFF), (char)((inPropertyID >> 8) & 0xFF), (char)(inPropertyID & 0xFF), 0 };
    LogToJava(std::string("HLE_AUDIO: AudioFileGetPropertyInfo запрошен неизвестный ID: ") + prop);
    
    if (outDataSize) *outDataSize = 128; 
    return 0;
}
extern "C" int wrap_AudioFileGetProperty(void* inAudioFile, uint32_t inPropertyID, uint32_t* ioDataSize, void* outPropertyData) {
    if (!inAudioFile || !outPropertyData || !ioDataSize) return -50;
    HLE_AudioFile* af = (HLE_AudioFile*)inAudioFile;
    if (inPropertyID == 0x64666D74) { // dfmt
        if (*ioDataSize >= 40) {
            memset(outPropertyData, 0, 40);
            double* sampleRate = (double*)outPropertyData;
            uint32_t* props = (uint32_t*)((uint8_t*)outPropertyData + 8);
            *sampleRate = af->sampleRate;
            props[0] = af->formatID;
            props[1] = (af->formatID == 0x6C70636D) ? 0xC : 0;
            props[2] = af->bytesPerPacket;
            props[3] = (af->formatID == 0x696D6134) ? 64 : 1;
            props[4] = (af->formatID == 0x6C70636D) ? props[2] : 0;
            props[5] = af->channels;
            props[6] = (af->formatID == 0x6C70636D) ? af->bitsPerSample : 0;
        }
        return 0;
    }
    if (inPropertyID == 0x62636E74) { // bcnt
        if (*ioDataSize >= 8) { *(uint64_t*)outPropertyData = af->dataSize; }
        else if (*ioDataSize >= 4) { *(uint32_t*)outPropertyData = (uint32_t)af->dataSize; }
        return 0;
    }
    if (inPropertyID == 0x70737A65 || inPropertyID == 0x70737562) { // psze or psub
        if (*ioDataSize >= 4) { *(uint32_t*)outPropertyData = af->bytesPerPacket; }
        return 0;
    }
    if (inPropertyID == 0x70636E74) { // pcnt
        uint64_t packets = af->bytesPerPacket > 0 ? (af->dataSize / af->bytesPerPacket) : 0;
        if (*ioDataSize >= 8) { *(uint64_t*)outPropertyData = packets; }
        else if (*ioDataSize >= 4) { *(uint32_t*)outPropertyData = (uint32_t)packets; }
        return 0;
    }

    char prop[5] = { (char)(inPropertyID >> 24), (char)((inPropertyID >> 16) & 0xFF), (char)((inPropertyID >> 8) & 0xFF), (char)(inPropertyID & 0xFF), 0 };
    LogToJava(std::string("HLE_AUDIO: AudioFileGetProperty запрошен неизвестный ID: ") + prop);

    memset(outPropertyData, 0, *ioDataSize); return 0;
}
extern "C" int wrap_AudioFileReadPackets(void* inAudioFile, uint8_t inUseCache, uint32_t* outNumBytes, void* outPacketDescriptions, int64_t inStartingPacket, uint32_t* ioNumPackets, void* outBuffer) {
    if (!inAudioFile || !ioNumPackets || !outBuffer) return -50;
    HLE_AudioFile* af = (HLE_AudioFile*)inAudioFile;
    uint32_t bytesPerPacket = af->bytesPerPacket;
    if (bytesPerPacket == 0) bytesPerPacket = 1;
    uint32_t reqPackets = *ioNumPackets;
    uint32_t bytesToRead = reqPackets * bytesPerPacket;
    FILE* f = VfsFopenAny(af->path, "rb");
    if (!f) { 
        LogToJava("HLE_AUDIO_ERROR: ReadPackets не смог открыть файл: " + af->path);
        *ioNumPackets = 0; if (outNumBytes) *outNumBytes = 0; return -39; 
    }
    fseek(f, af->dataOffset + (inStartingPacket * bytesPerPacket), SEEK_SET);
    size_t readBytes = fread(outBuffer, 1, bytesToRead, f);
    fclose(f);
    *ioNumPackets = (uint32_t)(readBytes / bytesPerPacket);
    if (outNumBytes) *outNumBytes = (uint32_t)readBytes;
    
    static int rp_log = 0;
    if (rp_log++ < 20) {
        LogToJava("HLE_AUDIO: Чтение пакетов из " + af->path + ". Запрошено пакетов: " + std::to_string(reqPackets) + ", прочитано байт: " + std::to_string(readBytes));
    }
    return 0;
}
extern "C" int wrap_AudioFileReadBytes(void* inAudioFile, uint8_t inUseCache, int64_t inStartingByte, uint32_t* ioNumBytes, void* outBuffer) {
    if (!inAudioFile || !ioNumBytes || !outBuffer) return -50;
    HLE_AudioFile* af = (HLE_AudioFile*)inAudioFile;
    uint32_t reqBytes = *ioNumBytes;
    FILE* f = VfsFopenAny(af->path, "rb");
    if (!f) { 
        LogToJava("HLE_AUDIO_ERROR: ReadBytes не смог открыть файл: " + af->path);
        *ioNumBytes = 0; return -39; 
    }
    fseek(f, af->dataOffset + inStartingByte, SEEK_SET);
    size_t readBytes = fread(outBuffer, 1, reqBytes, f);
    fclose(f);
    *ioNumBytes = (uint32_t)readBytes;
    
    static int rb_log = 0;
    if (rb_log++ < 20) {
        LogToJava("HLE_AUDIO: Чтение сырых байт из " + af->path + ". Запрошено: " + std::to_string(reqBytes) + ", прочитано: " + std::to_string(readBytes));
    }
    return 0;
}
// --- ExtAudioFile HLE ---
// Начиная с MCPE 0.3.0.0 звуки лежат в .m4a и игра берёт их через ExtAudioFile,
// который на iOS decodes-on-read. Здесь файл декодируется целиком в 16-битный PCM
// силами Android MediaCodec, а дальше отдаётся кусками, как того ждёт гость.
struct HLE_ExtAudioFile {
    std::string path;
    std::vector<uint8_t> pcm;
    int sampleRate;
    int channels;
    int64_t frames;
    int64_t readPos;
    HLE_ExtAudioFile() : sampleRate(44100), channels(1), frames(0), readPos(0) {}
};

static bool ExtAudioDecodeToPCM(HLE_ExtAudioFile* ef) {
    JNIEnv* env = GetJNIEnv(); if (!env || !g_mainActivity) return false;
    jclass clazz = env->GetObjectClass(g_mainActivity);

    // MediaExtractor умеет только настоящий файл, а игра с 0.3.0.0 читает звук из бандла.
    // Когда бандл — это .ipa, отдаём ей сам архив и срез внутри него.
    std::string archive; int64_t off = 0, len64 = 0;
    jbyteArray arr = nullptr;
    if (IpaGetStoredRange(ef->path, archive, off, len64)) {
        jmethodID mr = env->GetMethodID(clazz, "decodeAudioRangeJava", "(Ljava/lang/String;JJ)[B");
        if (mr) {
            jstring jarc = env->NewStringUTF(archive.c_str());
            arr = (jbyteArray)env->CallObjectMethod(g_mainActivity, mr, jarc, (jlong)off, (jlong)len64);
            env->DeleteLocalRef(jarc);
        }
    } else {
        jmethodID m = env->GetMethodID(clazz, "decodeAudioFileJava", "(Ljava/lang/String;)[B");
        if (!m) { env->DeleteLocalRef(clazz); return false; }
        jstring jpath = env->NewStringUTF(ef->path.c_str());
        arr = (jbyteArray)env->CallObjectMethod(g_mainActivity, m, jpath);
        env->DeleteLocalRef(jpath);
    }
    env->DeleteLocalRef(clazz);
    if (!arr) return false;
    jsize len = env->GetArrayLength(arr);
    if (len < 8) { env->DeleteLocalRef(arr); return false; }
    std::vector<uint8_t> raw((size_t)len);
    env->GetByteArrayRegion(arr, 0, len, (jbyte*)raw.data());
    env->DeleteLocalRef(arr);
    memcpy(&ef->sampleRate, raw.data(), 4);
    memcpy(&ef->channels, raw.data() + 4, 4);
    if (ef->channels < 1) ef->channels = 1;
    if (ef->sampleRate < 1) ef->sampleRate = 44100;
    ef->pcm.assign(raw.begin() + 8, raw.end());
    ef->frames = (int64_t)(ef->pcm.size() / (size_t)(2 * ef->channels));
    return true;
}

static void ExtAudioFillASBD(HLE_ExtAudioFile* ef, void* outData) {
    memset(outData, 0, 40);
    *(double*)outData = (double)ef->sampleRate;
    uint32_t* p = (uint32_t*)((uint8_t*)outData + 8);
    p[0] = 0x6C70636D;              // 'lpcm'
    p[1] = 0xC;                     // signed integer | packed
    p[2] = (uint32_t)(2 * ef->channels);
    p[3] = 1;
    p[4] = (uint32_t)(2 * ef->channels);
    p[5] = (uint32_t)ef->channels;
    p[6] = 16;
}

extern "C" int wrap_ExtAudioFileOpenURL(void* inURL, void** outExtAudioFile) {
    if (!outExtAudioFile) return -50;
    std::string path;
    if (inURL) {
        uint32_t* urlInst = (uint32_t*)inURL;
        if (urlInst[1]) {
            path = GetNSString((void*)urlInst[1]);
            if (!path.empty()) {
                if (path.find("file://") == 0) path = path.substr(7);
                if (path[0] != '/') path = g_appBundlePath + "/" + path;
            }
        }
    }
    if (path.empty()) {
        LogToJava("HLE_AUDIO_ERROR: ExtAudioFileOpenURL получил пустой путь");
        return -43;
    }
    HLE_ExtAudioFile* ef = new HLE_ExtAudioFile();
    ef->path = path;
    if (!ExtAudioDecodeToPCM(ef)) {
        LogToJava("HLE_AUDIO_ERROR: ExtAudioFileOpenURL не смог декодировать: " + path);
        delete ef;
        return -43;
    }
    LogToJava("HLE_AUDIO: ExtAudioFileOpenURL " + path + " -> " + std::to_string(ef->frames) + " кадров, " + std::to_string(ef->sampleRate) + " Гц, каналов: " + std::to_string(ef->channels));
    *outExtAudioFile = ef;
    return 0;
}

extern "C" int wrap_ExtAudioFileGetProperty(void* ref, uint32_t propID, uint32_t* ioSize, void* outData) {
    if (!ref || !ioSize || !outData) return -50;
    HLE_ExtAudioFile* ef = (HLE_ExtAudioFile*)ref;
    if (propID == 0x66666D74 || propID == 0x63666D74) { // 'ffmt' / 'cfmt'
        if (*ioSize < 40) return -50;
        ExtAudioFillASBD(ef, outData);
        *ioSize = 40;
        return 0;
    }
    if (propID == 0x2366726D) { // '#frm'
        if (*ioSize >= 8) { *(int64_t*)outData = ef->frames; *ioSize = 8; }
        else if (*ioSize >= 4) { *(int32_t*)outData = (int32_t)ef->frames; *ioSize = 4; }
        return 0;
    }
    char prop[5] = { (char)(propID >> 24), (char)((propID >> 16) & 0xFF), (char)((propID >> 8) & 0xFF), (char)(propID & 0xFF), 0 };
    LogToJava(std::string("HLE_AUDIO: ExtAudioFileGetProperty запрошен неизвестный ID: ") + prop);
    memset(outData, 0, *ioSize);
    return 0;
}

extern "C" int wrap_ExtAudioFileSetProperty(void* ref, uint32_t propID, uint32_t inSize, const void* inData) {
    return 0;
}

extern "C" int wrap_ExtAudioFileRead(void* ref, uint32_t* ioNumberFrames, void* ioData) {
    if (!ref || !ioNumberFrames || !ioData) return -50;
    HLE_ExtAudioFile* ef = (HLE_ExtAudioFile*)ref;
    uint32_t* abl = (uint32_t*)ioData;
    if (abl[0] < 1) { *ioNumberFrames = 0; return 0; }
    uint32_t* buf0 = abl + 1; // mNumberChannels, mDataByteSize, mData
    int64_t bytesPerFrame = 2 * ef->channels;
    int64_t want = (int64_t)*ioNumberFrames;
    int64_t avail = ef->frames - ef->readPos;
    if (want > avail) want = avail;
    int64_t capacityFrames = (int64_t)buf0[1] / bytesPerFrame;
    if (want > capacityFrames) want = capacityFrames;
    if (want < 0) want = 0;
    void* dst = (void*)(uintptr_t)buf0[2];
    if (want > 0 && dst) memcpy(dst, ef->pcm.data() + ef->readPos * bytesPerFrame, (size_t)(want * bytesPerFrame));
    buf0[1] = (uint32_t)(want * bytesPerFrame);
    ef->readPos += want;
    *ioNumberFrames = (uint32_t)want;
    return 0;
}

extern "C" int wrap_ExtAudioFileSeek(void* ref, int64_t inFrameOffset) {
    if (!ref) return -50;
    HLE_ExtAudioFile* ef = (HLE_ExtAudioFile*)ref;
    if (inFrameOffset < 0) inFrameOffset = 0;
    if (inFrameOffset > ef->frames) inFrameOffset = ef->frames;
    ef->readPos = inFrameOffset;
    return 0;
}

extern "C" int wrap_ExtAudioFileTell(void* ref, int64_t* outFrameOffset) {
    if (!ref || !outFrameOffset) return -50;
    *outFrameOffset = ((HLE_ExtAudioFile*)ref)->readPos;
    return 0;
}

