// Отдаём именно _Rep*, а не указатель на данные: гость после вызова сам считает
// данные как _Rep+1 и пишет туда строку. С указателем на данные всё съезжало на
// 12 байт — запись уходила за конец блока, а free приходил на его середину.
extern "C" void* wrap_cxx_string_Rep_S_create(size_t cap, size_t old_cap, void* alloc) {
    if (cap > old_cap && cap < 2 * old_cap) cap = 2 * old_cap;
    LibStdStringRep* rep = (LibStdStringRep*)malloc(sizeof(LibStdStringRep) + cap + 1);
    rep->length = 0; rep->capacity = cap; rep->refcount = 0;   // 0 — единственная ссылка
    ((char*)(rep + 1))[0] = 0;
    return rep;
}

// --- ТРЕЙСИНГ C-API ФУНКЦИЙ (СЕТЬ И ВРЕМЯ) ---
extern bool g_machOLoaded;

extern "C" void* wrap_mmap(void *addr, size_t length, int prot, int flags, int fd, off_t offset) {
    uint32_t lr = (uint32_t)__builtin_return_address(0);
    // Записи .ipa нельзя отобразить напрямую: они не выровнены, а то и сжаты.
    // Отдаём анонимную память с вычитанным содержимым — для чтения это неотличимо.
    if (IpaIsVirtualFd(fd)) {
        void* mem = mmap(addr, length, PROT_READ | PROT_WRITE,
                         MAP_PRIVATE | MAP_ANONYMOUS | (flags & MAP_FIXED), -1, 0);
        if (mem == MAP_FAILED) {
            LogToJava("C-API-ERROR: mmap записи .ipa не удался, len=" + std::to_string(length));
            return MAP_FAILED;
        }
        size_t done = 0;
        while (done < length) {
            ssize_t r = IpaPread(fd, (char*)mem + done, length - done, (off64_t)offset + done);
            if (r <= 0) break;
            done += (size_t)r;
        }
        if (!(prot & PROT_WRITE)) mprotect(mem, length, prot);
        LogToBlackBox("C-API-MEM: [mmap] из .ipa len=" + std::to_string(length) +
                      " прочитано=" + std::to_string(done));
        return mem;
    }
    void* res = mmap(addr, length, prot, flags, fd, offset);
    if (res == MAP_FAILED) {
        LogToJava("C-API-ERROR: mmap(" + std::to_string(length) + " bytes, prot=" + std::to_string(prot) + ") FAILED! Caller: " + GetModuleInfoForAddress(lr));
    } else if (g_machOLoaded) {
        LogToBlackBox("C-API-MEM: [mmap] addr=" + std::to_string((uintptr_t)res) + " len=" + std::to_string(length) + " Caller: " + GetModuleInfoForAddress(lr));
    }
    return res;
}

extern "C" int wrap_munmap(void *addr, size_t length) {
    uint32_t lr = (uint32_t)__builtin_return_address(0);
    if (g_machOLoaded) {
        LogToBlackBox("C-API-MEM: [munmap] addr=" + std::to_string((uintptr_t)addr) + " len=" + std::to_string(length) + " Caller: " + GetModuleInfoForAddress(lr));
    }
    return munmap(addr, length);
}

extern "C" int wrap_connect(int sockfd, const struct sockaddr *addr, socklen_t addrlen) {
    struct sockaddr_storage ss; socklen_t sl;
    if (!SockaddrIOSToLinux(addr, addrlen, &ss, &sl)) { errno = EAFNOSUPPORT; return -1; }
    int r = connect(sockfd, (struct sockaddr*)&ss, sl);
    LogToJava("C-API-TRACE: connect(fd=" + std::to_string(sockfd) + " port=" +
              std::to_string(ntohs(((struct sockaddr_in*)&ss)->sin_port)) + ") -> " + std::to_string(r));
    return r;
}
extern "C" void* wrap_gethostbyname(const char *name) { 
    std::string sName = name ? name : "null";
    LogToJava("C-API-TRACE: gethostbyname(" + sName + ") ИМИТАЦИЯ (127.0.0.1)"); 
    
    static struct hostent he;
    static char hostname[] = "localhost";
    static char* aliases[] = { nullptr };
    static uint32_t addr = 0x0100007F; // 127.0.0.1 в network byte order
    static char* addr_list[] = { (char*)&addr, nullptr };
    
    he.h_name = hostname;
    he.h_aliases = aliases;
    he.h_addrtype = AF_INET;
    he.h_length = 4;
    he.h_addr_list = addr_list;
    
    return &he; 
}
extern "C" uint64_t wrap_mach_absolute_time() { 
    return Stub_mach_absolute_time();
}

